  document.head.insertAdjacentHTML('beforeend', `<style>#bb .logo{font:700 italic 44px/.78 'Cormorant Garamond',serif!important;letter-spacing:-2px!important}#bb button{cursor:pointer!important}#bb .back{display:inline-flex!important;align-items:center!important;white-space:nowrap!important}#bb .row>.primary,#bb .row>.secondary,#bb .auth-actions>.primary,#bb .auth-actions>.secondary,#bb .auth-button{height:48px;min-height:48px;font-family:'DM Sans',sans-serif!important;font-size:16px;font-weight:400;line-height:1}#bb .auth-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-top:20px}#bb .auth-actions>button{width:100%;margin:0!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important}#bb .auth-button{width:100%;margin-top:20px!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important}#bb #forgot{display:inline-flex!important;align-items:center!important;justify-content:center!important;margin-top:12px!important}#bb #resetform .row{margin-top:20px}#bb #resetform .row>button{width:100%;margin:0!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;font-family:'DM Sans',sans-serif!important;font-size:16px;font-weight:400;line-height:1}#bb #newpasswordform>.primary{width:100%;height:48px;min-height:48px;margin-top:20px!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;font-family:'DM Sans',sans-serif!important;font-size:16px;font-weight:400;line-height:1}</style>`);
