  document.head.insertAdjacentHTML('beforeend', '<style>#bb button[data-t]{position:relative!important;justify-content:flex-start!important}#bb button[data-t] .tag{position:absolute!important;left:280px!important;top:25px!important}#bb button[data-delete-event]{display:block!important;margin:-43px 0 10px auto!important;min-height:28px!important;padding:0 8px!important;font-size:10px!important}</style>');
