  function remember(view,data={}){const next={birdieBoard:true,view,data},current=history.state;if(current?.birdieBoard&&current.view===view&&JSON.stringify(current.data)===JSON.stringify(data))return;if(!current?.birdieBoard)history.replaceState(next,'',location.href);else history.pushState(next,'',location.href)}
  function page(html,inApp=false){root.innerHTML=`<div class="shell"><header class="top"><button id="home" class="logo">Birdie <i>Board</i></button>${inApp?'<div class="head-actions"><button id="account" class="secondary">Account</button><button id="out" class="secondary">Sign out</button></div>':''}</header>${html}</div>`;document.getElementById('home').onclick=()=>user?dashboard():auth();document.getElementById('account')?.addEventListener('click',account);document.getElementById('out')?.addEventListener('click',()=>supabase.auth.signOut())}
  function passwordRecovery(){page(`<section class="card"><p class="kick">PASSWORD RECOVERY</p><h2>Reset your password.</h2><p class="muted">Enter your account email and we’ll send a secure reset link.</p><p id="msg" class="error"></p><form id="resetform"><label class="field">Email address<input id="email" type="email" autocomplete="email" required></label><div class="row"><button class="primary">Send reset link</button><button id="back" class="secondary" type="button">Back to sign in</button></div></form></section>`);document.getElementById('back').onclick=()=>auth();document.getElementById('resetform').onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('msg');msg.textContent='Sending reset link…';const{error}=await supabase.auth.resetPasswordForEmail(document.getElementById('email').value.trim(),{redirectTo:'https://birdieboard.uk/'});msg.textContent=error?error.message:'If that email has a Birdie Board account, a reset link is on its way.'}}
  function newPassword(){page(`<section class="card"><p class="kick">PASSWORD RECOVERY</p><h2>Choose a new password.</h2><p class="muted">Use at least eight characters, then sign in with your new password.</p><p id="msg" class="error"></p><form id="newpasswordform"><label class="field">New password<input id="password" type="password" minlength="8" autocomplete="new-password" required></label><label class="field">Confirm new password<input id="confirm" type="password" minlength="8" autocomplete="new-password" required></label><button class="primary">Save new password</button></form></section>`);document.getElementById('newpasswordform').onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('msg'),password=document.getElementById('password').value;if(password!==document.getElementById('confirm').value){msg.textContent='Your passwords do not match.';return}msg.textContent='Saving your new password…';const{error}=await supabase.auth.updateUser({password});if(error){msg.textContent=error.message;return}await supabase.auth.signOut();auth('Password updated. Please sign in.')}}
  function auth(message='',signup=false){const extra=signup?`<label class="field">First name<input id="first" required></label><label class="field">Last name<input id="last" required></label><label class="field">Exact handicap<input id="hcp" type="number" min="0" max="54" step=".1" required></label>`:'';const buttonStyle=`style="height:48px;min-height:48px;margin:0!important;padding:0!important;display:flex!important;align-items:center!important;justify-content:center!important;text-align:center!important;font-family:Arial,sans-serif;font-size:16px;font-weight:400;line-height:1"`;page(`<section class="card"><p class="kick">WELCOME TO THE CLUBHOUSE</p><h2>${signup?'Create your player profile.':'Live golf scoring.'}</h2><p class="muted">${signup?'Register to join clubs and play live tournaments.':'Sign in to organise rounds and follow live leaderboards.'}</p><p id="msg" class="error">${e(message)}</p><form id="authform">${extra}<label class="field">Email address<input id="email" type="email" required></label><label class="field">Password<input id="password" type="password" minlength="8" required></label>${signup?'<label class="field">Confirm password<input id="confirm" type="password" minlength="8" required></label>':''}<div class="row"><button class="primary" ${buttonStyle}>${signup?'Sign Up':'Sign in'}</button><button id="switch" class="secondary" type="button" ${buttonStyle}>${signup?'Back to sign in':'Sign Up'}</button></div>${signup?'':'<button id="forgot" class="small" type="button">Forgot password?</button>'}</form></section>`);document.getElementById('switch').onclick=()=>auth('',!signup);if(!signup)document.getElementById('forgot').onclick=passwordRecovery;document.getElementById('authform').onsubmit=async x=>{x.preventDefault();const msg=document.getElementById('msg'),email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;if(!signup){msg.textContent='Signing in…';const{error}=await supabase.auth.signInWithPassword({email,password});msg.textContent=error?.message||'';return}const h=+document.getElementById('hcp').value;if(password!==document.getElementById('confirm').value){msg.textContent='Your passwords do not match.';return}msg.textContent='Creating account…';const{error}=await supabase.auth.signUp({email,password,options:{data:{first_name:document.getElementById('first').value.trim(),last_name:document.getElementById('last').value.trim(),handicap:String(h)},emailRedirectTo:'https://birdieboard.uk/'}});if(error){msg.textContent=error.message;return}await supabase.auth.signOut();auth('Account created. Check your email to confirm it, then sign in.')}}
  async function account(){const{data:profile,error}=await supabase.rpc('get_my_profile');if(error){page(`<section class="card"><p class="kick">ACCOUNT</p><h2>Your player profile</h2><p class="error">${e(error.message)}</p><button id="back" class="secondary">Back to clubhouse</button></section>`,true);document.getElementById('back').onclick=dashboard;return}page(`<section class="card"><p class="kick">ACCOUNT</p><h2>Your player profile</h2><p class="muted">Keep these details current so your club and tournament handicap information is accurate.</p><p id="profilemsg" class="error"></p><form id="profileform"><label class="field">First name<input id="first" maxlength="60" value="${e(profile?.first_name||'')}" required></label><label class="field">Last name<input id="last" maxlength="80" value="${e(profile?.last_name||'')}" required></label><label class="field">Exact handicap<input id="hcp" type="number" min="0" max="54" step=".1" value="${e(profile?.handicap??'')}" required></label><button class="primary auth-button">Save profile</button></form></section><section class="card"><p class="kick">SECURITY</p><h2>Change password</h2><p id="passwordmsg" class="error"></p><form id="passwordform"><label class="field">New password<input id="newpassword" type="password" minlength="8" autocomplete="new-password" required></label><label class="field">Confirm new password<input id="confirmnewpassword" type="password" minlength="8" autocomplete="new-password" required></label><button class="secondary auth-button">Change password</button></form></section><button id="back" class="back">← Back to clubhouse</button>`,true);document.getElementById('back').onclick=dashboard;document.getElementById('profileform').onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('profilemsg');msg.textContent='Saving profile…';const{error}=await supabase.rpc('update_my_profile',{profile_first_name:document.getElementById('first').value,profile_last_name:document.getElementById('last').value,profile_handicap:+document.getElementById('hcp').value});msg.textContent=error?error.message:'Profile saved.'};document.getElementById('passwordform').onsubmit=async event=>{event.preventDefault();const msg=document.getElementById('passwordmsg'),password=document.getElementById('newpassword').value;if(password!==document.getElementById('confirmnewpassword').value){msg.textContent='Your passwords do not match.';return}msg.textContent='Updating password…';const{error}=await supabase.auth.updateUser({password});if(error){msg.textContent=error.message;return}document.getElementById('passwordform').reset();msg.textContent='Password updated.'}}
  async function getClubs(){const{data,error}=await supabase.rpc('get_my_social_clubs');if(error){console.error('Could not load clubs:',error.message);clubs=[];return}clubs=data||[]}
  async function dashboard(){await getClubs();const clubList=clubs.map(c=>`<button class="item" data-club="${c.id}"><span><b>${e(c.name)}</b><small>${c.role==='owner'||c.role==='admin'?'Owner / organiser':'Club member'}</small></span><span class="tag">Open</span></button>`).join('')||'<p class="muted">Create or join a social club to build your regular playing group.</p>';page(`<section class="card"><p class="kick">YOUR CLUBHOUSE</p><h2>Welcome back</h2><p class="muted">Open a social club to see its members, event history, and tournaments.</p></section><section class="card"><p class="kick">SOCIAL CLUBS</p>${clubList}<div class="row"><button id="newclub" class="secondary">Create club</button><button id="joinclub" class="secondary">Join with code</button></div></section>`,true);document.getElementById('newclub').onclick=createClub;document.getElementById('joinclub').onclick=joinClub;document.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>clubDetail(b.dataset.club))}
  async function clubDetail(clubId){await getClubs();const clubInfo=clubs.find(c=>c.id===clubId);const owner=['owner','admin'].includes(clubInfo?.role);const[{data:roster,error:re},{data:events,error:te}]=await Promise.all([supabase.rpc('get_social_club_members',{target_club:clubId}),supabase.rpc('get_social_club_tournaments',{target_club:clubId})]);if(re||te){page(`<p class="error">${e(re?.message||te?.message)}</p>`,true);return}const people=(roster||[]).map(m=>`<div class="item"><span><b>${e(name(m))}</b><small>Exact handicap: ${e(m.handicap??'Not set')}</small></span><span class="tag">${e(m.role)}</span></div>`).join('')||'<p class="muted">No members yet.</p>';const eventList=(events||[]).map(t=>`<button class="item" data-t="${t.id}"><span><b>${e(t.name)}</b><small>${e(t.course_name||'Course pending')} · ${t.starts_at?new Date(t.starts_at).toLocaleDateString():'Date pending'}</small></span><span class="tag">${t.is_finalised?'final':'open'}</span></button>`).join('')||'<p class="muted">No events yet.</p>';page(`<button id="back" class="back">← All clubs</button><section class="card"><p class="kick">SOCIAL CLUB</p><h2>${e(clubInfo?.name)}</h2>${owner?`<p class="muted">Share this join code with Birdie Board users.</p><p class="note" style="font-size:22px;letter-spacing:3px;text-align:center">${e(clubInfo.invite_code)}</p>`:'<p class="muted">You are a member of this club.</p>'}<button id="newt" class="primary">Create tournament</button></section><section class="card"><p class="kick">MEMBERS</p>${people}</section><section class="card"><p class="kick">EVENT HISTORY</p>${eventList}</section>`,true);back.onclick=dashboard;newt.onclick=()=>createTournament(clubId);document.querySelectorAll('[data-t]').forEach(b=>b.onclick=()=>tournament(b.dataset.t))}
  function createClub(){page(`<button class="back" id="back">← Back</button><section class="card"><p class="kick">NEW SOCIAL CLUB</p><h2>Your regular playing group</h2><p id="msg" class="error"></p><form id="form"><label class="field">Club name<input id="clubname" maxlength="80" required placeholder="Saturday Golf Society"></label><button class="primary">Create club</button></form></section>`,true);back.onclick=dashboard;form.onsubmit=async x=>{x.preventDefault();const{data,error}=await supabase.rpc('create_social_club',{club_name:clubname.value});if(error){msg.textContent=error.message;return}page(`<section class="card"><p class="kick">CLUB CREATED</p><h2>${e(data.name)}</h2><p class="muted">Share this code with people who already have a Birdie Board account.</p><p class="note" style="font-size:24px;letter-spacing:3px;text-align:center">${e(data.invite_code)}</p><button id="clubhome" class="primary">Go to clubhouse</button></section>`,true);document.getElementById('clubhome').onclick=dashboard}}
  function joinClub(){page(`<button class="back" id="back">← Back</button><section class="card"><p class="kick">JOIN A CLUB</p><h2>Enter an invite code</h2><p id="msg" class="error"></p><form id="form"><label class="field">Club code<input id="code" maxlength="8" required></label><button class="primary">Join club</button></form></section>`,true);back.onclick=dashboard;form.onsubmit=async x=>{x.preventDefault();const{error}=await supabase.rpc('join_social_club',{code:code.value});if(error){msg.textContent=error.message;return}dashboard()}}
  function scorecardImport(){return `<p class="kick" style="margin-top:20px">IMPORT SCORECARD</p><p class="muted">Import a screenshot or scorecard photo. OCR looks for an SI or S.I. row; always check the imported values.</p><input id="scorecardimage" type="file" accept="image/*" hidden><button id="pickscorecard" class="secondary" type="button">Import scorecard photo</button><button id="readscorecard" class="secondary" type="button" disabled style="margin-left:8px">Read SI with OCR</button><p id="ocrmsg" class="error"></p>`}
  function scorecardFields(holes=[]){return `<div class="scorecard-grid"><b>HOLE</b><b>PAR</b><b>SI</b>${Array.from({length:18},(_,i)=>{const hole=holes.find(h=>+h.hole_number===i+1);return `<span class="hole">${i+1}</span><input data-par="${i+1}" type="number" min="3" max="6" value="${hole?.par??4}" required><input data-si="${i+1}" type="number" min="1" max="18" value="${hole?.stroke_index??i+1}" required>`}).join('')}</div>`}
  function findStrokeIndices(text){for(const match of text.matchAll(/\bS\.?\s*I\.?\b/gi)){const values=(text.slice(match.index,match.index+260).match(/\b(?:[1-9]|1[0-8])\b/g)||[]).map(Number);for(let i=0;i<=values.length-18;i++){const row=values.slice(i,i+18);if(new Set(row).size===18&&Math.min(...row)===1&&Math.max(...row)===18)return row}}return null}
  function setupScorecardImport(){scorecardFile=null;const button=document.getElementById('readscorecard'),message=document.getElementById('ocrmsg'),picker=document.getElementById('scorecardimage'),setFile=file=>{if(!file)return;if(file.size>12*1024*1024){message.textContent='Please use an image smaller than 12 MB.';return}scorecardFile=file;button.disabled=false;message.textContent=`Ready to read ${file.name}.`};document.getElementById('pickscorecard')?.addEventListener('click',()=>picker?.click());picker?.addEventListener('change',event=>setFile(event.target.files[0]));button?.addEventListener('click',async()=>{if(!scorecardFile)return;button.disabled=true;message.textContent='Reading the SI row…';let worker;try{if(!window.Tesseract){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@6/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(new Error('OCR library could not be loaded'));document.head.appendChild(script)})}worker=await window.Tesseract.createWorker('eng');const result=await worker.recognize(scorecardFile),indices=findStrokeIndices(result.data.text);if(!indices)throw new Error('No complete SI row found');document.querySelectorAll('[data-si]').forEach((input,index)=>input.value=indices[index]);message.textContent='SI row imported. Please check all 18 values before saving.'}catch(error){message.textContent='We could not read a complete SI row. Please enter the values manually.'}finally{if(worker)await worker.terminate();button.disabled=false}})}
  function createTournament(clubId){const selected=clubs.find(c=>c.id===clubId);page(`<button class="back" id="back">← Back to ${e(selected?.name||'club')}</button><section class="card"><p class="kick">NEW TOURNAMENT</p><h2>Set the round</h2><p class="muted">${e(selected?.name||'Social club')} · create the course scorecard now, then add players and groups.</p><p id="msg" class="error"></p><form id="form"><input id="club" type="hidden" value="${e(clubId)}"><label class="field">Tournament name<input id="tname" required placeholder="Saturday Stableford"></label><label class="field">Course name<input id="cname" required placeholder="Riverside Golf Club"></label><label class="field">Start date<input id="date" type="datetime-local"></label>${scorecardImport()}<p class="kick" style="margin-top:20px">COURSE SCORECARD</p><p class="muted">Enter the par and stroke index for each hole. You can amend this before scoring starts.</p>${scorecardFields()}<button class="primary auth-button">Create tournament</button></form></section>`,true);back.onclick=()=>clubDetail(clubId);setupScorecardImport();form.onsubmit=makeTournament}
  async function makeTournament(event){event.preventDefault();const pars=[...document.querySelectorAll('[data-par]')].map(input=>+input.value),indices=[...document.querySelectorAll('[data-si]')].map(input=>+input.value);if(pars.some(par=>par<3||par>6)){msg.textContent='Each hole par must be between 3 and 6.';return}if(new Set(indices).size!==18||Math.min(...indices)!==1||Math.max(...indices)!==18){msg.textContent='Use every stroke index from 1 to 18 once.';return}msg.textContent='Creating tournament…';const{data:course,error:ce}=await supabase.from('courses').insert({name:cname.value.trim(),created_by:user.id}).select().single();if(ce){msg.textContent=ce.message;return}const holes=Array.from({length:18},(_,i)=>({course_id:course.id,hole_number:i+1,par:pars[i],stroke_index:indices[i]}));const{error:he}=await supabase.from('course_holes').insert(holes);if(he){msg.textContent=he.message;return}const{data:t,error:te}=await supabase.from('tournaments').insert({name:tname.value.trim(),course_id:course.id,club_id:club.value,created_by:user.id,starts_at:date.value||null,status:'live'}).select().single();if(te){msg.textContent=te.message;return}await supabase.rpc('add_club_player_to_tournament',{target_tournament:t.id,target_player:user.id,target_handicap:null});tournament(t.id)}
  function additionalRounds(count){return Array.from({length:Math.max(0,count-1)},(_,index)=>{const round=index+2;return `<section class="note" style="margin-top:12px"><b>Round ${round}</b><label class="field">Course name<input data-round-course="${round}" required placeholder="Course for round ${round}"></label><label class="field">Round date<input data-round-date="${round}" type="datetime-local"></label></section>`}).join('')}
  async function makeMultiTournament(event){event.preventDefault();const roundCount=Math.max(1,Math.min(20,+document.getElementById('roundcount')?.value||1)),pars=[...document.querySelectorAll('[data-par]')].map(input=>+input.value),indices=[...document.querySelectorAll('[data-si]')].map(input=>+input.value);if(new Set(indices).size!==18||Math.min(...indices)!==1||Math.max(...indices)!==18){msg.textContent='Use every stroke index from 1 to 18 once.';return}msg.textContent='Creating tournament…';const createCourse=async(name)=>{const{data:course,error}=await supabase.from('courses').insert({name:name.trim(),created_by:user.id}).select().single();if(error)throw error;const{error:holeError}=await supabase.from('course_holes').insert(pars.map((par,index)=>({course_id:course.id,hole_number:index+1,par,stroke_index:indices[index]})));if(holeError)throw holeError;return course};try{const firstCourse=await createCourse(cname.value),{data:t,error}=await supabase.from('tournaments').insert({name:tname.value.trim(),course_id:firstCourse.id,club_id:club.value,created_by:user.id,starts_at:date.value||null,status:'live'}).select().single();if(error)throw error;const rounds=[{tournament_id:t.id,round_number:1,course_id:firstCourse.id,starts_at:date.value||null}];for(let round=2;round<=roundCount;round++){const course=await createCourse(document.querySelector(`[data-round-course="${round}"]`).value),roundDate=document.querySelector(`[data-round-date="${round}"]`).value;rounds.push({tournament_id:t.id,round_number:round,course_id:course.id,starts_at:roundDate||null})}const{error:roundError}=await supabase.from('tournament_rounds').insert(rounds);if(roundError)throw roundError;await supabase.rpc('add_club_player_to_tournament',{target_tournament:t.id,target_player:user.id,target_handicap:null});tournament(t.id)}catch(error){msg.textContent=error.message}}
  function stableford(gross,hcp,hole){const strokes=Math.floor(hcp/18)+(hole.stroke_index<=hcp%18?1:0);return Math.max(0,hole.par-(gross-strokes)+2)}
  async function tournament(id){if(channel)await supabase.removeChannel(channel);const[{data:t,error:te},{data:members,error:me},{data:scores},{data:holes},{data:overrides},{data:groups},{data:gms}]=await Promise.all([supabase.from('tournaments').select('id,name,club_id,created_by,is_finalised,courses(id,name)').eq('id',id).single(),supabase.from('tournament_members').select('user_id,role,playing_handicap,profiles(first_name,last_name,display_name,handicap)').eq('tournament_id',id),supabase.from('hole_scores').select('player_id,hole_number,gross_score').eq('tournament_id',id),supabase.from('course_holes').select('hole_number,par,stroke_index').eq('course_id',null).order('hole_number'),supabase.from('score_overrides').select('*').eq('tournament_id',id),supabase.from('tournament_groups').select('*').eq('tournament_id',id),supabase.from('tournament_group_members').select('*')]);
    if(te||me){page(`<p class="error">${e(te?.message||me?.message)}</p>`,true);return}const{data:roster}=await supabase.from('club_members').select('user_id,profiles(first_name,last_name,display_name,handicap)').eq('club_id',t.club_id);const{data:realHoles}=await supabase.from('course_holes').select('hole_number,par,stroke_index').eq('course_id',t.courses.id).order('hole_number');const hs=realHoles||[];const map=new Map((scores||[]).map(s=>[`${s.player_id}-${s.hole_number}`,s.gross_score])),om=new Map((overrides||[]).map(o=>[`${o.player_id}-${o.hole_number}`,o.stableford_points]));const mine=(members||[]).find(m=>m.user_id===user.id),manage=t.created_by===user.id||['organizer','organiser'].includes(mine?.role),scored=new Set((gms||[]).filter(gm=>(groups||[]).some(g=>g.id===gm.group_id&&g.scorer_id===user.id)).map(x=>x.user_id));scored.add(user.id);const editable=(members||[]).filter(m=>manage||scored.has(m.user_id));const board=(members||[]).map(m=>{let pts=0,thru=0;hs.forEach(h=>{const gross=map.get(`${m.user_id}-${h.hole_number}`);if(gross){thru++;pts+=om.get(`${m.user_id}-${h.hole_number}`)??stableford(gross,Number(m.playing_handicap??m.profiles?.handicap??0),h)}});return{m,pts,thru}}).sort((a,b)=>b.pts-a.pts);const groupText=(groups||[]).map(g=>{const ps=(gms||[]).filter(x=>x.group_id===g.id).map(x=>name((members||[]).find(m=>m.user_id===x.user_id)?.profiles)).join(', ');return `<p class="note"><b>${e(g.name)}</b> · scorer: ${e(name((members||[]).find(m=>m.user_id===g.scorer_id)?.profiles))}<br>${e(ps)}</p>`}).join('')||'<p class="muted">No playing groups yet.</p>';const scoreUi=t.is_finalised?'':`<section class="card"><p class="kick">SCORE ENTRY</p><h2>${manage?'Review & score':'Your group scores'}</h2><p class="muted">Enter gross strokes. Saving updates the live leaderboard.</p>${editable.map(m=>`<div class="note"><b>${e(name(m.profiles))}</b> · HCP ${e(m.playing_handicap??m.profiles?.handicap??0)}</div>${hs.map(h=>`<label class="score"><span>Hole ${h.hole_number}<small> P${h.par} · SI${h.stroke_index}</small></span><input data-score="${m.user_id}|${h.hole_number}" type="number" min="1" max="20" value="${map.get(`${m.user_id}-${h.hole_number}`)||''}"></label>`).join('')}`).join('')}<button id="save" class="primary">Save scores</button></section>`;const manager=manage&&!t.is_finalised?management(t,members||[],roster||[]):'';page(`<button id="back" class="back">← All tournaments</button><section class="card"><p class="kick">${t.is_finalised?'FINALISED':'LIVE'} TOURNAMENT</p><h2>${e(t.name)}</h2><p class="muted">${e(t.courses.name)} · Stableford</p>${t.is_finalised?'<p class="note">Results are locked. An organiser may reopen this event if a correction is needed.</p>':''}</section><section class="card"><p class="kick">LIVE LEADERBOARD</p>${board.map((x,i)=>`<div class="item"><span>${i+1}. <b>${e(name(x.m.profiles))}</b><small>${x.thru}/18</small></span><b>${x.pts} pts</b></div>`).join('')}</section><section class="card"><p class="kick">PLAYING GROUPS</p>${groupText}</section>${manager}${scoreUi}`,true);back.onclick=dashboard;document.getElementById('save')?.addEventListener('click',()=>saveScores(id));document.getElementById('addplayer')?.addEventListener('click',()=>addPlayer(id));document.getElementById('groupform')?.addEventListener('submit',x=>makeGroup(x,id));document.getElementById('overrideform')?.addEventListener('submit',x=>override(x,id));document.getElementById('final')?.addEventListener('click',()=>finalise(id,!t.is_finalised));channel=supabase.channel(`scores-${id}`).on('postgres_changes',{event:'*',schema:'public',table:'hole_scores',filter:`tournament_id=eq.${id}`},()=>tournament(id)).subscribe()}
  function management(t,members,roster){const inTournament=new Set(members.map(m=>m.user_id));const available=roster.filter(m=>!inTournament.has(m.user_id)).map(m=>`<option value="${m.user_id}">${e(name(m.profiles))}</option>`).join('');const players=members.map(m=>`<option value="${m.user_id}">${e(name(m.profiles))}</option>`).join('');setTimeout(()=>loadScorecardEditor(t),0);return `<section class="card"><p class="kick">ORGANISER CONTROLS</p><h2>Players, groups & review</h2><p id="manageerr" class="error"></p><label class="field">Add a club member<select id="clubplayer"><option value="">Select player</option>${available}</select></label><button id="addplayer" class="secondary">Add player</button><form id="groupform"><label class="field">Playing group name<input id="gname" required placeholder="Group 1"></label><label class="field">Group scorer<select id="gscorer">${players}</select></label><div class="checks">${members.map(m=>`<label><input type="checkbox" name="gplayer" value="${m.user_id}"> ${e(name(m.profiles))}</label>`).join('')}</div><button class="secondary" style="margin-top:10px">Create group</button></form><form id="overrideform"><p class="kick" style="margin-top:18px">MANUAL STABLEFORD OVERRIDE</p><label class="field">Player<select id="oplayer">${players}</select></label><label class="field">Hole<input id="ohole" type="number" min="1" max="18" required></label><label class="field">Points<select id="opoints">${Array.from({length:11},(_,i)=>`<option>${i}</option>`).join('')}</select></label><label class="field">Reason<input id="oreason" minlength="2" maxlength="240" required placeholder="Scorecard correction"></label><button class="secondary">Save override</button></form><form id="scorecardform"><p class="kick" style="margin-top:18px">EDIT COURSE SCORECARD</p><p class="muted">Correct par or stroke indices before scoring. You can also import an SI row from a photo or screenshot.</p>${scorecardImport()}${scorecardFields()}<button class="secondary auth-button">Save scorecard changes</button></form><button id="final" class="primary" style="margin-top:16px">${t.is_finalised?'Reopen tournament':'Finalise and lock results'}</button><button id="delete" class="secondary" style="margin-top:10px">Delete tournament</button></section>`}
  async function loadScorecardEditor(t){const form=document.getElementById('scorecardform');if(!form)return;setupScorecardImport();const{data:holes,error}=await supabase.from('course_holes').select('hole_number,par,stroke_index').eq('course_id',t.courses.id).order('hole_number');if(error){document.getElementById('manageerr').textContent=error.message;return}(holes||[]).forEach(hole=>{const par=document.querySelector(`[data-par="${hole.hole_number}"]`),si=document.querySelector(`[data-si="${hole.hole_number}"]`);if(par)par.value=hole.par;if(si)si.value=hole.stroke_index});form.onsubmit=event=>saveScorecard(event,t.id);document.getElementById('delete')?.addEventListener('click',()=>deleteTournament(t.id,t.club_id))}
  async function saveScorecard(event,tid){event.preventDefault();const pars=[...document.querySelectorAll('[data-par]')].map(input=>+input.value),indices=[...document.querySelectorAll('[data-si]')].map(input=>+input.value),message=document.getElementById('manageerr');if(pars.some(par=>par<3||par>6)){message.textContent='Each hole par must be between 3 and 6.';return}if(new Set(indices).size!==18||Math.min(...indices)!==1||Math.max(...indices)!==18){message.textContent='Use every stroke index from 1 to 18 once.';return}message.textContent='Saving scorecard…';const scorecard=pars.map((par,index)=>({hole_number:index+1,par,stroke_index:indices[index]}));const{error}=await supabase.rpc('update_tournament_scorecard',{target_tournament:tid,scorecard});message.textContent=error?error.message:'Scorecard updated.';if(!error)tournament(tid)}
