  async function editTournamentSettings(id){const{data:t,error}=await supabase.from('tournaments').select('id,name,club_id').eq('id',id).single();if(error){alert(error.message);return}const{data:rounds}=await supabase.from('tournament_rounds').select('id').eq('tournament_id',id);page(`<button id="back" class="back">← Back to club</button><section class="card"><p class="kick">EDIT TOURNAMENT</p><h2>Event settings</h2><p id="msg" class="error"></p><form id="editsettings"><label class="field">Tournament name<input id="eventname" value="${e(t.name)}" required></label><label class="field">Rounds planned<input id="eventrounds" type="number" min="1" max="20" value="${rounds?.length||1}" required></label><button class="primary auth-button">Save settings</button></form></section>`,true);back.onclick=()=>clubDetail(t.club_id);editsettings.onsubmit=async e=>{e.preventDefault();const{error}=await supabase.from('tournaments').update({name:eventname.value.trim()}).eq('id',id);msg.textContent=error?error.message:'Tournament name saved. Round changes are managed from Tournament Preparation.';if(!error)setTimeout(()=>tournament(id),500)}}
