  function startTournamentSetup(clubId){preparation={clubId,courses:[],rounds:[]};page(`<button id="back" class="back">← Back to club</button><section class="card"><p class="kick">NEW TOURNAMENT · 1 OF 3</p><h2>Tournament details</h2><form id="setupone"><label class="field">Tournament name<input id="setupname" required placeholder="Saturday Stableford"></label><label class="field">How many rounds?<select id="setuprounds">${Array.from({length:20},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select></label><label class="field">How many distinct courses?<select id="setupcourses">${Array.from({length:20},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('')}</select></label><button class="primary auth-button">Set up courses</button></form></section>`,true);back.onclick=()=>clubDetail(clubId);setupone.onsubmit=e=>{e.preventDefault();preparation.name=setupname.value.trim();preparation.roundCount=+setuprounds.value;preparation.courseCount=+setupcourses.value;courseSetup(0)}}
  function courseSetup(index){if(index>=preparation.courseCount)return roundSetup();page(`<button id="back" class="back">← Back</button><section class="card"><p class="kick">COURSE ${index+1} OF ${preparation.courseCount} · 2 OF 3</p><h2>Course scorecard</h2><p id="msg" class="error"></p><form id="courseform"><label class="field">Course name<input id="coursename" required placeholder="Weymouth Golf Club"></label>${scorecardImport()}${scorecardFields()}<button class="primary auth-button">Save course</button></form></section>`,true);back.onclick=()=>index?courseSetup(index-1):startTournamentSetup(preparation.clubId);setupScorecardImport();courseform.onsubmit=e=>{e.preventDefault();const pars=[...document.querySelectorAll('[data-par]')].map(x=>+x.value),si=[...document.querySelectorAll('[data-si]')].map(x=>+x.value);if(new Set(si).size!==18||Math.min(...si)!==1||Math.max(...si)!==18){msg.textContent='Use every stroke index from 1 to 18 once.';return}preparation.courses[index]={name:coursename.value.trim(),pars,si};courseSetup(index+1)}}
  function roundSetup(){page(`<button id="back" class="back">← Back to courses</button><section class="card"><p class="kick">ROUND ASSIGNMENTS · 3 OF 3</p><h2>Dates and courses</h2><p id="msg" class="error"></p><form id="roundform">${Array.from({length:preparation.roundCount},(_,i)=>`<section class="note"><b>Round ${i+1}</b><label class="field">Date<input data-rdate="${i+1}" type="datetime-local" required></label><label class="field">Course<select data-rcourse="${i+1}">${preparation.courses.map((c,j)=>`<option value="${j}">${e(c.name)}</option>`).join('')}</select></label></section>`).join('')}<button class="primary auth-button">Create tournament</button></form></section>`,true);back.onclick=()=>courseSetup(preparation.courseCount-1);roundform.onsubmit=savePreparedTournament}
  async function savePreparedTournament(e){e.preventDefault();msg.textContent='Creating tournament…';try{const created=[];for(const c of preparation.courses){const{data,error}=await supabase.from('courses').insert({name:c.name,created_by:user.id}).select().single();if(error)throw error;const{error:holes}=await supabase.from('course_holes').insert(c.pars.map((par,i)=>({course_id:data.id,hole_number:i+1,par,stroke_index:c.si[i]})));if(holes)throw holes;created.push(data)}const rounds=Array.from({length:preparation.roundCount},(_,i)=>({course:created[+document.querySelector(`[data-rcourse="${i+1}"]`).value],date:document.querySelector(`[data-rdate="${i+1}"]`).value})),first=rounds[0];const{data:t,error}=await supabase.from('tournaments').insert({name:preparation.name,course_id:first.course.id,club_id:preparation.clubId,created_by:user.id,starts_at:first.date,status:'live'}).select().single();if(error)throw error;const{error:roundError}=await supabase.from('tournament_rounds').insert(rounds.map((r,i)=>({tournament_id:t.id,round_number:i+1,course_id:r.course.id,starts_at:r.date})));if(roundError)throw roundError;await supabase.rpc('add_club_player_to_tournament',{target_tournament:t.id,target_player:user.id,target_handicap:null});tournament(t.id)}catch(error){msg.textContent=error.message}}
  const showAuth=auth,showPasswordRecovery=passwordRecovery,showNewPassword=newPassword,showDashboard=dashboard,showAccount=account,showClubDetail=clubDetail,showCreateClub=createClub,showJoinClub=joinClub,showCreateTournament=createTournament,showTournament=tournament;
  auth=(message='',signup=false)=>{if(message==='Account created. Check your email to confirm it, then sign in.')message='Account created. Check your email — including your junk or spam folder — for the verification link, then sign in.';remember('auth',{message,signup});return showAuth(message,signup)};
