  clubDetail=async clubId=>{remember('clubDetail',{clubId});await showClubDetail(clubId);document.querySelectorAll('.kick').forEach(label=>{if(label.textContent==='EVENT HISTORY')label.textContent='EVENTS'});const club=clubs.find(item=>item.id===clubId),{data:events}=await supabase.rpc('get_social_club_tournaments',{target_club:clubId});(events||[]).forEach(event=>{const detail=document.querySelector(`[data-t="${event.id}"] small`);if(detail)detail.textContent=`${event.course_name||'Course pending'} · ${event.starts_at?new Intl.DateTimeFormat('en-GB').format(new Date(event.starts_at)):'Date pending'}`});if(!['owner','admin'].includes(club?.role))return;(events||[]).filter(event=>!event.is_finalised).forEach(event=>{const eventButton=document.querySelector(`[data-t="${event.id}"]`);if(!eventButton||eventButton.nextElementSibling?.dataset.deleteEvent)return;const button=document.createElement('button');button.className='small';button.dataset.deleteEvent=event.id;button.textContent='Delete';button.style.cssText='margin:0 0 0 8px;min-height:28px;padding:0 8px;font-size:10px';button.onclick=async()=>{if(!confirm('Delete this event? This is only possible before scores are recorded.'))return;const{error}=await supabase.rpc('delete_tournament',{target_tournament:event.id});if(error){alert(error.message);return}clubDetail(clubId)};eventButton.insertAdjacentElement('afterend',button)})};
