  tournament=async id=>{remember('tournament',{id});await showTournament(id);document.getElementById('delete')?.remove();document.getElementById('final')?.remove();document.getElementById('overrideform')?.remove();document.getElementById('groupform')?.remove();document.querySelectorAll('.card').forEach(card=>{const label=card.querySelector('.kick')?.textContent;if(label==='SCORE ENTRY'||label==='LIVE LEADERBOARD')card.remove()});const[{data:event},{data:rounds}]=await Promise.all([supabase.from('tournaments').select('club_id,created_by').eq('id',id).maybeSingle(),supabase.from('tournament_rounds').select('id,round_number,starts_at,course_id,courses(name)').eq('tournament_id',id).order('round_number')]);const organiser=event?.created_by===user.id,firstCard=document.querySelector('.card');if(firstCard&&rounds?.length)firstCard.insertAdjacentHTML('afterend',`<section class="card"><p class="kick">TOURNAMENT PREPARATION</p><h2>${rounds.length} round${rounds.length===1?'':'s'} planned</h2>${rounds.map(round=>`<div class="item"><span><b>Round ${round.round_number}</b><small>${e(round.courses?.name||'Course pending')}</small></span><span>${round.starts_at?new Intl.DateTimeFormat('en-GB').format(new Date(round.starts_at)):'Date pending'}${organiser?`<button class="small" data-edit-round="${round.id}" style="margin-left:8px">Edit</button>`:''}</span></div>`).join('')}</section>`);if(rounds?.length>1||new Set((rounds||[]).map(round=>round.course_id)).size>1)document.getElementById('scorecardform')?.closest('.card')?.remove();const back=document.getElementById('back');if(back&&event?.club_id){back.textContent='← Back to club';back.onclick=()=>clubDetail(event.club_id)}};
