  function arrangeEventActions(){document.querySelectorAll('button[data-t]').forEach(eventButton=>{if(eventButton.parentElement?.classList.contains('event-row'))return;const id=eventButton.dataset.t,del=document.querySelector(`[data-delete-event="${id}"]`),edit=document.querySelector(`[data-edit-event="${id}"]`);if(!del||!edit)return;const row=document.createElement('div'),actions=document.createElement('div');row.className='event-row';actions.className='event-actions';eventButton.replaceWith(row);row.append(eventButton,actions);actions.append(edit,del);edit.style.cssText='';del.style.cssText='';});}
